// ─────────────────────────────────────────────────────────────
// src/stem/policy/verdict.recorder.ts
// ─────────────────────────────────────────────────────────────
//
// POLICY_REAFFERENCE P1 — the policy-verdict record/replay seam.
//
// The arbiter is an external, potentially non-deterministic oracle — exactly
// like the LLM (`completion.recorder.ts`) and the transport (`inbound.recorder`).
// A refused invocation's effect on cognition (a graded outcome the
// ReafferenceEngine consumes) must be reproducible, so the verdict at the tick
// it was decided is captured here.
//
// Mirrors inbound.recorder.ts deliberately: this ships the CAPTURE half now (a
// willId-keyed sink), and defines the re-feed SOURCE interface for when
// deterministic external-I/O re-execution is built. A refusal is applied by the
// harness between steps through `confirmExecution`, the same lifecycle as a host
// ack — so like host acks, its full deterministic re-execution rides the same
// (still-deferred) mechanism, and the seam is ready for it.
//
// DETERMINISM: a verdict is keyed by ( tick, intentId ) — both pure functions of
// seed-pinned state (the executor emits `agency.invocation` deterministically),
// so a recorded verdict pairs unambiguously with its call on replay. When a
// source is registered the arbiter is NOT consulted; the recorded verdict is
// returned, so replay can never re-enter a live (or absent) PDP.
//
// Both registries are keyed by willId so each Will routes to its own
// recorder/source — matching completion.recorder.ts / inbound.recorder.ts.
// ─────────────────────────────────────────────────────────────

import type { Tick, Timestamp } from '#core/types'
import type { PolicyDecision, DenialFinality, PolicyCounterfactual } from '#stem/policy/arbiter'

export interface PolicyVerdictRecord {
  tick:            Tick
  willId:          string
  /** The awaiting `agency.intent` id — the correlation handle, end to end. */
  intentId:        string
  /** The motor schema (ability) the verdict was about. */
  schema:          string
  /** The arbiter that decided, recorded for audit. */
  arbiter:         string
  decision:        PolicyDecision
  reasonCode?:     string
  finality?:       DenialFinality
  counterfactual?: PolicyCounterfactual
  timestamp:       Timestamp
}

// ── Capture sink ─────────────────────────────────────────────

export interface PolicyVerdictSink {
  recordVerdict( record: PolicyVerdictRecord ): void
}

const _sinks = new Map<string, PolicyVerdictSink>()

export function setVerdictRecorder( willId: string, sink: PolicyVerdictSink ): void {
  _sinks.set( willId, sink )
}

export function clearVerdictRecorder( willId: string ): void {
  _sinks.delete( willId )
}

export function getVerdictRecorder( willId: string ): PolicyVerdictSink | undefined {
  return _sinks.get( willId )
}

// ── Replay re-feed source (re-execution deferred) ────────────

/**
 * Supplies recorded verdicts back during a deterministic re-execution, keyed by
 * willId. Returns the verdict recorded for `( tick, intentId )`, or undefined
 * for a miss — a strict caller (the enforcement point) treats a miss under an
 * active source as a divergence rather than silently re-consulting a live PDP.
 */
export interface PolicyVerdictSource {
  verdictFor( tick: Tick, intentId: string ): PolicyVerdictRecord | undefined
}

/**
 * Strict re-feed source backed by an array of recorded verdicts. Keyed by
 * ( tick, intentId ); duplicate keys within a run are not expected (one verdict
 * per invocation) but consume FIFO if present.
 */
export class RecordedVerdictSource implements PolicyVerdictSource {
  private _byKey = new Map<string, PolicyVerdictRecord[]>()

  constructor( verdicts: readonly PolicyVerdictRecord[] ){
    for( const v of verdicts ){
      const key   = keyOf( v.tick, v.intentId )
      const queue = this._byKey.get( key )
      if( queue ) queue.push( v )
      else this._byKey.set( key, [ v ] )
    }
  }

  verdictFor( tick: Tick, intentId: string ): PolicyVerdictRecord | undefined {
    const queue = this._byKey.get( keyOf( tick, intentId ) )
    if( !queue || queue.length === 0 ) return undefined
    return queue.shift()
  }
}

function keyOf( tick: Tick, intentId: string ): string {
  return `${tick}�${intentId}`
}

const _sources = new Map<string, PolicyVerdictSource>()

export function setVerdictSource( willId: string, source: PolicyVerdictSource ): void {
  _sources.set( willId, source )
}

export function clearVerdictSource( willId: string ): void {
  _sources.delete( willId )
}

export function getVerdictSource( willId: string ): PolicyVerdictSource | undefined {
  return _sources.get( willId )
}
